// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetActivity What the server is doing right now (for the header activity indicator).
	// (GET /activity)
	GetActivity(ctx context.Context, request GetActivityRequestObject) (GetActivityResponseObject, error)

	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the current session token.
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// PinLogin Sign in by choosing a profile and entering its 4-digit PIN (managed profiles without a PIN need none).
	// (POST /auth/pin)
	PinLogin(ctx context.Context, request PinLoginRequestObject) (PinLoginResponseObject, error)
	// ListSignInProfiles Profiles for the "Who's watching?" sign-in screen. Empty when PIN sign-in isn't allowed from the caller's network.
	// (GET /auth/profiles)
	ListSignInProfiles(ctx context.Context, request ListSignInProfilesRequestObject) (ListSignInProfilesResponseObject, error)
	// ListDevices Signed-in devices. Admins see every user's devices; others see their own.
	// (GET /devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// RevokeDevice Sign a device out.
	// (DELETE /devices/{deviceId})
	RevokeDevice(ctx context.Context, request RevokeDeviceRequestObject) (RevokeDeviceResponseObject, error)
	// BrowseFilesystem List directories under the configured browse roots, for the library folder picker (admin only).
	// (GET /filesystem/browse)
	BrowseFilesystem(ctx context.Context, request BrowseFilesystemRequestObject) (BrowseFilesystemResponseObject, error)
	// HomeHubs Rows for the Home screen (Continue Watching, Recently Added…).
	// (GET /hubs/home)
	HomeHubs(ctx context.Context, request HomeHubsRequestObject) (HomeHubsResponseObject, error)
	// GetImage Artwork resized to a cached width. Responses are immutable (a changed image gets a new id).
	// (GET /images/{artworkId})
	GetImage(ctx context.Context, request GetImageRequestObject) (GetImageResponseObject, error)

	// (GET /items/{itemId})
	GetItem(ctx context.Context, request GetItemRequestObject) (GetItemResponseObject, error)
	// ListItemChildren Seasons of a show, episodes of a season, albums of an artist, tracks of an album.
	// (GET /items/{itemId}/children)
	ListItemChildren(ctx context.Context, request ListItemChildrenRequestObject) (ListItemChildrenResponseObject, error)
	// SearchMatches Candidate matches for Fix Match (admin only, movies and shows).
	// (GET /items/{itemId}/match)
	SearchMatches(ctx context.Context, request SearchMatchesRequestObject) (SearchMatchesResponseObject, error)
	// ApplyMatch Match the item to a specific provider entry and refresh its metadata (admin only).
	// (PUT /items/{itemId}/match)
	ApplyMatch(ctx context.Context, request ApplyMatchRequestObject) (ApplyMatchResponseObject, error)
	// EditItem Edit metadata fields (admin only). Edited fields are locked so agents won't overwrite them.
	// (PATCH /items/{itemId}/metadata)
	EditItem(ctx context.Context, request EditItemRequestObject) (EditItemResponseObject, error)
	// NextItem The episode after this one (Up Next), if any.
	// (GET /items/{itemId}/next)
	NextItem(ctx context.Context, request NextItemRequestObject) (NextItemResponseObject, error)
	// RefreshItem Re-download metadata for a matched movie or show, keeping locked fields (admin only).
	// (POST /items/{itemId}/refresh)
	RefreshItem(ctx context.Context, request RefreshItemRequestObject) (RefreshItemResponseObject, error)

	// (DELETE /items/{itemId}/watched)
	MarkUnwatched(ctx context.Context, request MarkUnwatchedRequestObject) (MarkUnwatchedResponseObject, error)
	// MarkWatched Mark watched (shows, seasons, artists and albums mark everything inside).
	// (POST /items/{itemId}/watched)
	MarkWatched(ctx context.Context, request MarkWatchedRequestObject) (MarkWatchedResponseObject, error)
	// ListLibraries Libraries visible to the current user.
	// (GET /libraries)
	ListLibraries(ctx context.Context, request ListLibrariesRequestObject) (ListLibrariesResponseObject, error)
	// CreateLibrary Create a library (admin only).
	// (POST /libraries)
	CreateLibrary(ctx context.Context, request CreateLibraryRequestObject) (CreateLibraryResponseObject, error)
	// ScanAllLibraries Queue a scan of every library (admin only).
	// (POST /libraries/scan)
	ScanAllLibraries(ctx context.Context, request ScanAllLibrariesRequestObject) (ScanAllLibrariesResponseObject, error)
	// DeleteLibrary Delete a library and its metadata (admin only). Media files are never touched.
	// (DELETE /libraries/{libraryId})
	DeleteLibrary(ctx context.Context, request DeleteLibraryRequestObject) (DeleteLibraryResponseObject, error)

	// (GET /libraries/{libraryId})
	GetLibrary(ctx context.Context, request GetLibraryRequestObject) (GetLibraryResponseObject, error)
	// UpdateLibrary Update a library (admin only). Type cannot be changed.
	// (PATCH /libraries/{libraryId})
	UpdateLibrary(ctx context.Context, request UpdateLibraryRequestObject) (UpdateLibraryResponseObject, error)
	// ListLibraryItems Top-level items of a library (movies, shows, artists or videos), or all items of a given type.
	// (GET /libraries/{libraryId}/items)
	ListLibraryItems(ctx context.Context, request ListLibraryItemsRequestObject) (ListLibraryItemsResponseObject, error)
	// CancelLibraryScan Cancel a queued or running scan (admin only).
	// (DELETE /libraries/{libraryId}/scan)
	CancelLibraryScan(ctx context.Context, request CancelLibraryScanRequestObject) (CancelLibraryScanResponseObject, error)
	// ScanLibrary Queue a scan of one library (admin only). Returns immediately; poll the library for progress.
	// (POST /libraries/{libraryId}/scan)
	ScanLibrary(ctx context.Context, request ScanLibraryRequestObject) (ScanLibraryResponseObject, error)
	// GetLogs Recent server log lines, newest last (admin only).
	// (GET /logs)
	GetLogs(ctx context.Context, request GetLogsRequestObject) (GetLogsResponseObject, error)

	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update your own profile, password, PIN or preferences.
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)

	// (GET /people/{personId}/photo)
	GetPersonPhoto(ctx context.Context, request GetPersonPhotoRequestObject) (GetPersonPhotoResponseObject, error)
	// BandwidthTest Random bytes for the client to time its download speed (used for automatic remote quality).
	// (GET /playback/bandwidth-test)
	BandwidthTest(ctx context.Context, request BandwidthTestRequestObject) (BandwidthTestResponseObject, error)
	// ListPlaybackSessions Active playback sessions. Administrators see everyone's; others see their own.
	// (GET /playback/sessions)
	ListPlaybackSessions(ctx context.Context, request ListPlaybackSessionsRequestObject) (ListPlaybackSessionsResponseObject, error)
	// StartPlayback Start playing an item. The server decides between direct play, direct stream and transcode for this device and network.
	// (POST /playback/sessions)
	StartPlayback(ctx context.Context, request StartPlaybackRequestObject) (StartPlaybackResponseObject, error)
	// StopPlayback Stop playback. Administrators can stop anyone's session.
	// (DELETE /playback/sessions/{sessionId})
	StopPlayback(ctx context.Context, request StopPlaybackRequestObject) (StopPlaybackResponseObject, error)
	// ReportPlayback Report position and state (every ~10 seconds, and on pause/seek). Updates resume points and watched status.
	// (PATCH /playback/sessions/{sessionId})
	ReportPlayback(ctx context.Context, request ReportPlaybackRequestObject) (ReportPlaybackResponseObject, error)
	// GetPlexImport Whether a Plex database is available, import progress and the last report (admin only).
	// (GET /plex-import)
	GetPlexImport(ctx context.Context, request GetPlexImportRequestObject) (GetPlexImportResponseObject, error)
	// StartPlexImport Start an import in the background (admin only). Safe to run again; nothing is duplicated.
	// (POST /plex-import)
	StartPlexImport(ctx context.Context, request StartPlexImportRequestObject) (StartPlexImportResponseObject, error)
	// PreviewPlexImport Read a snapshot of the Plex database and show what an import would do (admin only).
	// (POST /plex-import/preview)
	PreviewPlexImport(ctx context.Context, request PreviewPlexImportRequestObject) (PreviewPlexImportResponseObject, error)
	// ListProfiles Profiles that can be switched to from this device (Plex Home equivalent).
	// (GET /profiles)
	ListProfiles(ctx context.Context, request ListProfilesRequestObject) (ListProfilesResponseObject, error)
	// SwitchProfile Switch this device to another profile. Requires that profile's PIN (or password if it has no PIN).
	// (POST /profiles/{userId}/switch)
	SwitchProfile(ctx context.Context, request SwitchProfileRequestObject) (SwitchProfileResponseObject, error)
	// Search Search titles across the libraries the user can access.
	// (GET /search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// GetSettings Server settings (admin only). Secret values are never returned, only whether they are set.
	// (GET /settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// UpdateSettings Partially update settings (admin only). Omitted sections and fields are unchanged.
	// (PATCH /settings)
	UpdateSettings(ctx context.Context, request UpdateSettingsRequestObject) (UpdateSettingsResponseObject, error)
	// CompleteSetup First-run setup. Creates the admin account. Only allowed while setupRequired is true.
	// (POST /setup)
	CompleteSetup(ctx context.Context, request CompleteSetupRequestObject) (CompleteSetupResponseObject, error)
	// GetHealth Liveness/readiness probe.
	// (GET /system/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetSystemInfo Public server identity and status (used for discovery and connection checks).
	// (GET /system/info)
	GetSystemInfo(ctx context.Context, request GetSystemInfoRequestObject) (GetSystemInfoResponseObject, error)
	// ListUsers All users (admin only).
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Create a user or managed profile (admin only).
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// DeleteUser Delete a user and their devices, watch history and playlists (admin only). The last admin cannot be deleted.
	// (DELETE /users/{userId})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// UpdateUser Update a user (admin only). Omitted fields are unchanged.
	// (PATCH /users/{userId})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetActivity operation middleware
func (sh *strictHandler) GetActivity(w http.ResponseWriter, r *http.Request) {
	var request GetActivityRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetActivity(ctx, request.(GetActivityRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetActivity")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetActivityResponseObject); ok {
		if err := validResponse.VisitGetActivityResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

